# -*- coding: utf-8 -*-
from pathlib import Path
import json, shutil
P=Path(__file__).resolve().parents[2];H=P/'production'/'hyperframes'
actions=json.loads((P/'production'/'action_manifest_v01.json').read_text())
cast=[{'id':k,'name':next(a['name_ko'] for a in actions if a['character']==k)} for k in ['mizu','pon','kon','sumi','nemu','akari','kasa']]
data=json.dumps({'cast':cast,'actions':actions},ensure_ascii=False)
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>인간인 척! — 캐릭터 아트와 동작</title>
<style>*{box-sizing:border-box}body{margin:0;color:#29362f;background:#f4f0e7;font-family:system-ui,sans-serif}header{padding:28px 4vw;border-bottom:1px solid #d9dfd0;display:flex;justify-content:space-between;gap:20px;align-items:center}h1{margin:0;font-size:26px;letter-spacing:-1px}header p{margin:6px 0 0;color:#677567;font-size:14px}a{color:#376b63;text-decoration:none}button,select{font:inherit;color:inherit}button{border:1px solid #c9d5c9;border-radius:14px;background:#fffaf0;padding:10px 17px;cursor:pointer}button[aria-pressed=true]{background:#386d62;color:white;border-color:#386d62}.cast{display:flex;gap:10px;padding:20px 4vw;flex-wrap:wrap}.panel{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(290px,.65fr);gap:22px;margin:0 4vw 30px}.card{background:#fffaf1;border:1px solid #e0e1d2;border-radius:24px;overflow:hidden}.sheet{width:100%;display:block}.info{padding:20px}.info h2{margin:0 0 12px;font-size:20px}.art{width:100%;height:360px;object-fit:contain}.check{background-color:#edf1e8;background-image:linear-gradient(45deg,#dce4d8 25%,transparent 25%),linear-gradient(-45deg,#dce4d8 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#dce4d8 75%),linear-gradient(-45deg,transparent 75%,#dce4d8 75%);background-size:24px 24px;background-position:0 0,0 12px,12px -12px,-12px 0}.links{display:flex;gap:15px;flex-wrap:wrap;font-size:14px}.motion{margin:0 4vw 40px;padding:24px;display:grid;grid-template-columns:1fr 1fr;gap:26px}video{width:100%;max-height:512px;display:block;border-radius:16px}.notice{padding:12px 16px;background:#edf0e2;border-radius:14px;font-size:14px;line-height:1.6;color:#596553}select{width:100%;margin:15px 0;padding:12px;border:1px solid #ccd6c7;border-radius:12px;background:#fffdf6}dl{display:grid;grid-template-columns:70px 1fr;gap:12px;font-size:14px;line-height:1.6}dt{color:#748071}dd{margin:0}.foot{padding:0 4vw 30px;color:#748071;font-size:12px}.pill{display:inline-block;font-size:12px;border-radius:20px;background:#dceadd;padding:5px 10px}.status{font-size:12px;color:#768172;margin:10px 0}footer{padding:20px 4vw;border-top:1px solid #d9dfd0}@media(max-width:800px){.panel,.motion{grid-template-columns:1fr}header{align-items:flex-start;flex-direction:column}.art{height:300px}}</style>
<header><div><h1>인간인 척!</h1><p>e.v.e games · 7명 캐릭터 아트 / 91개 동작 시안 · v01</p></div><a href="eve_games_art_motion_v01.zip" download>전체 묶음 다운로드 ↗</a></header>
<nav class="cast" aria-label="캐릭터 선택" id="cast"></nav>
<main><div class="panel"><section class="card"><img class="sheet" id="sheet" alt="개별 캐릭터 시트"><div class="info links"><a id="sheetDownload" download>시트 PNG ↗</a><a id="prompt" target="_blank">시트 생성 프롬프트 ↗</a></div></section><section class="card"><img class="art check" id="base" alt="투명 기본 캐릭터 아트"><div class="info"><h2 id="name"></h2><div class="links"><a id="baseDownload" download>투명 기본 이미지 ↗</a><a id="shadow" download>분리된 바닥 그림자 ↗</a></div><p class="status">3D 렌더 스타일의 기본 아트. 능력 효과와 그림자는 분리했습니다.</p></div></section></div>
<section class="card motion"><div><video class="check" id="video" controls muted playsinline></video><p id="videoStatus" class="status"></p><div class="links"><a id="webm" download>투명 WebM ↗</a><a id="mp4" download>MP4 확인용 ↗</a><a id="model" download>Blender 원본 ↗</a></div></div><div><span class="pill">별도 제작한 3D 동작 시안</span><h2>움직임 확인</h2><p class="notice">동작 시안은 캐릭터 구조와 연기를 검토하기 위한 간단한 3D 모델입니다. 왼쪽 이미지의 최종 아트를 그대로 리깅한 영상과는 구분됩니다.</p><select id="action" aria-label="동작 선택"></select><dl id="details"></dl><div class="links"><a id="docs" target="_blank">전체 동작 기준·프롬프트 ↗</a><a href="production/CHARACTER_RULES.md" target="_blank">신체·위장 기준 ↗</a></div></div></section></main><footer>고정 카메라 · 단독 캐릭터 · 제자리 걷기 · 투명 배경 · 영상 내부 자막 및 장면 전환 없음</footer>
<script>const DATA=__DATA__;let current='mizu';let action='idle';const $=s=>document.getElementById(s);function show(){const c=DATA.cast.find(c=>c.id===current);document.querySelectorAll('#cast button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.id===current));$('sheet').src=`art/${current}/${current}_sheet_${current==='nemu'?'v02':'v01'}.png`;$('base').src=`art/${current}/${current}_base_v01.png`;$('name').textContent=c.name;$('sheetDownload').href=$('sheet').src;$('baseDownload').href=$('base').src;$('shadow').href=`art/${current}/${current}_shadow_v01.svg`;$('prompt').href=`art/${current}/${current}_sheet_${current==='nemu'?'v02':'v01'}_prompt.md`;$('docs').href=`art/${current}/${current}_actions_v01.md`;$('model').href=`production/models/${current}_motion_study_v01.blend`;$('action').innerHTML='';DATA.actions.filter(a=>a.character===current).forEach(a=>{const o=document.createElement('option');o.value=a.action;o.textContent=a.action.replaceAll('_',' ')+' · '+a.recommended_seconds+'초';$('action').append(o)});$('action').value=action;motion()}function motion(){const a=DATA.actions.find(a=>a.character===current&&a.action===action);const stem=`production/animations/${current}/${current}_${action}_v01`;$('video').src=stem+'.webm';$('video').loop=a.loop;$('webm').href=stem+'.webm';$('mp4').href=stem+'_preview.mp4';$('videoStatus').textContent='512 × 512 · 24fps · '+(a.loop?'반복':'단발')+' · '+a.recommended_seconds+'초';$('details').innerHTML='';[['목적',a.purpose],['시작',a.start_pose],['끝',a.end_pose],['연기',a.acting]].forEach(([k,v])=>{const dt=document.createElement('dt');dt.textContent=k;const dd=document.createElement('dd');dd.textContent=v;$('details').append(dt,dd)})}$('action').addEventListener('change',e=>{action=e.target.value;motion()});DATA.cast.forEach(c=>{const b=document.createElement('button');b.textContent=c.name;b.dataset.id=c.id;b.onclick=()=>{current=c.id;show()};$('cast').append(b)});$('video').addEventListener('error',()=>{$('videoStatus').textContent='브라우저가 투명 WebM을 재생하지 못하면 MP4 확인용 파일을 열어 주세요.'});show();</script></html>'''.replace('__DATA__',data)
(P/'index.html').write_text(html)
H.mkdir(exist_ok=True);(H/'clips').mkdir(exist_ok=True);(H/'assets').mkdir(exist_ok=True)
for a in actions:
    ident=a['character']+'_'+a['action'];duration=a['recommended_seconds'];file=a['file']
    src=P/'production'/'animations'/a['character']/file
    if src.exists():shutil.copy2(src,H/'assets'/file)
    comp=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><script src="../assets/gsap.min.js"></script><style>html,body{{margin:0;width:512px;height:512px;background:transparent;overflow:hidden}}#root{{position:relative;width:100%;height:100%;background:transparent}}.clip{{position:absolute;inset:0;width:100%;height:100%;object-fit:contain}}</style></head><body><div id="root" data-composition-id="{ident}" data-width="512" data-height="512" data-duration="{duration}"><video id="{ident}-video" class="clip" src="../assets/{file}" data-start="0" data-duration="{duration}" data-track-index="0" muted playsinline></video></div><script>window.__timelines["{ident}"]=gsap.timeline({{paused:true}});</script></body></html>'''
    (H/'clips'/(ident+'.html')).write_text(comp)
    if ident=='mizu_idle':(H/'index.html').write_text(comp.replace('../assets/','assets/'))
(H/'BRIEF.md').write_text('---\nworkflow: general-video\nflow: automation\nstoryboard: no\nmessage: "Seven yokai characters, complete independent game motion studies"\ndestination: game asset review\naspect: square\nlanguage: none\n---\n\nUser authorized all sheets, transparent base art and all motions. No camera movement, text, scenery, portal or other characters in each clip. Native Blender rigid-part rigs provide separate 3D motion studies; image_gen creates canonical art sheets and alpha base art. Each clip is independently editable in HyperFrames; no montage is requested.\n')
(H/'design.md').write_text('# Design truth\n\nAnimal Crossing-like rounded matte toy 3D game art, fixed orthographic downward camera. Primary subject only; no typography in exported clips. Transparent canvas, no ground shadow. Canonical character sheets are distinct from procedural 3D motion studies. All anatomy counts, potion sides and costume colors are fixed. No transitions between independent clips.\n')
print('Wrote gallery and 91 independent HyperFrames clip wrappers')
